def main():
    import sys
    input = sys.stdin.read
    S = input().strip()

    # Count occurrences of each character
    char_count = {}
    for char in S:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Create a dictionary for count frequencies
    count_frequency = {}
    for count in char_count.values():
        if count in count_frequency:
            count_frequency[count] += 1
        else:
            count_frequency[count] = 1

    # Check the condition for each occurrence count
    for freq in count_frequency.values():
        if freq != 0 and freq != 2:
            print('No')
            return

    print('Yes')
